# Hypothesis: 3 -> 0 (empty), 4 <-> 6 swap
input_grid = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
    [4, 4, 4, 4, 4, 4, 4, 4, 4],
    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
]

hypothesis4 = [[0]*9 for _ in range(5)]
for i in range(5):
    for j in range(9):
        c = input_grid[i][j]
        if c == 4:
            hypothesis4[i][j] = 6
        elif c == 6:
            hypothesis4[i][j] = 4
        else:  # c == 3
            hypothesis4[i][j] = 0  # empty

print("Hypothesis 4 (3->0):")
for row in hypothesis4:
    print(row)

# Let me also try 3->1 and 3->2
hypothesis4b = [[0]*9 for _ in range(5)]
for i in range(5):
    for j in range(9):
        c = input_grid[i][j]
        if c == 4:
            hypothesis4b[i][j] = 6
        elif c == 6:
            hypothesis4b[i][j] = 4
        else:  # c == 3
            hypothesis4b[i][j] = 1

print("\nHypothesis 4b (3->1):")
for row in hypothesis4b:
    print(row)

input_grid = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
    [4, 4, 4, 4, 4, 4, 4, 4, 4],
    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
]

# 180 degree rotation (which is transpose + flip both, equivalent to reversing both axes)
rotated_180 = [row[::-1] for row in input_grid][::-1]

# Color swap
output = [[0]*9 for _ in range(5)]
for i in range(5):
    for j in range(9):
        c = rotated_180[i][j]
        if c == 4:
            output[i][j] = 6
        elif c == 6:
            output[i][j] = 4
        else:
            output[i][j] = 1

print("180 rotation + color swap:")
for row in output:
    print(row)

input_grid = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
