    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
]

# Hypothesis: same shape, simple color swap, 3->1
output = [[0]*9 for _ in range(5)]
for i in range(5):
    for j in range(9):
        c = input_grid[i][j]
        if c == 4:
            output[i][j] = 6
        elif c == 6:
            output[i][j] = 4
        else:
            output[i][j] = 1

print("Same shape 5x9, 4↔6, 3→1:")
for row in output:
    print(row)

input_grid = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
    [4, 4, 4, 4, 4, 4, 4, 4, 4],
    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
]

output = [[0]*5 for _ in range(9)]
for i in range(5):
    for j in range(9):
        c = input_grid[i][j]
        if c == 4:
            output[j][i] = 6
        elif c == 6:
            output[j][i] = 4
        else:
            output[j][i] = 3  # keep 3s as 3s

print("Transpose, 4↔6, 3→3:")
for row in output:
    print(row)

# Alternative: keep cross as 4s, background becomes 6s, 3s become 0s
output = [[0]*9 for _ in range(5)]
for i in range(5):
    for j in range(9):
        c = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
    [4, 4, 4, 4, 4, 4, 4, 4, 4],
    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
][i][j]
        if c == 4:
            output[i][j] = 4
        elif c == 6:
            output[i][j] = 6
        else:
            output[i][j] = 0

print("Keep 4s, 6, 3→0:")
for row in output:
    print(row)

# Rotate 90 CW: new[i][j] = old[n-1-j][i]
n_rows, n_cols = 5, 9
input_grid = [
    [6, 6, 3, 6, 4, 6, 6, 6, 6],
    [6, 3, 3, 3, 4, 6, 6, 6, 6],
    [4, 4, 4, 4, 4, 4, 4, 4, 4],
    [6, 6, 6, 6, 4, 6, 6, 6, 6],
    [6, 6, 6, 6, 4, 6, 6, 6, 6]
]

rotated_90 = [[0]*5 for _ in range(9)]
for i in range(n_rows):
    for j in range(n_cols):
        rotated_90[n_cols-1-j][i] = input_grid[i][j]

# Color swap + 3→1
output = [[0]*5 for _ in range(9)]
for i in range(9):
    for j in range(5):
        c = rotated_90[i][j]
        if c == 4:
            output[i][j] = 6
        elif c == 6:
            output[i][j] = 4
        else:
            output[i][j] = 1

print("Rotate 90 CW + swap colors + 3→1:")
for row in output:
    print(row)

